-- Accounts, identities, sessions, tokens and teams (M7 step 3a, architecture v0.63).
--
-- Ids are UUID v7, generated by the service: they appear in URLs and in object
-- store keys (sources/<submission>.zip), so they reveal no counts and can be
-- made before the row is inserted (an upload names its object first), and
-- they are time ordered, so a primary key index grows at its right edge as a
-- bigserial's does. Enumerations are text with a CHECK, so adding a value is
-- a one-line migration and a row reads the same in psql as on the wire.

CREATE TABLE users (
    id           uuid        PRIMARY KEY,
    display_name text        NOT NULL CHECK (char_length(display_name) BETWEEN 1 AND 64),
    created_at   timestamptz NOT NULL DEFAULT now()
);
-- Members are added by display name as well as by id.
CREATE INDEX users_display_name_lower ON users (lower(display_name));

-- One row per linked provider account. The key is the provider's subject id
-- (GitHub's numeric user id, Google's OIDC `sub`), never the email: the
-- email and name are display data as the provider last reported them.
CREATE TABLE identities (
    provider   text        NOT NULL CHECK (provider IN ('github', 'google')),
    subject    text        NOT NULL CHECK (char_length(subject) BETWEEN 1 AND 255),
    user_id    uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    name       text,
    email      text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT identities_pkey PRIMARY KEY (provider, subject),
    -- An account links each provider at most once.
    CONSTRAINT identities_user_provider UNIQUE (user_id, provider)
);

-- Portal sessions. The cookie carries 128 random bits signed with the
-- session key; the row is keyed by their SHA-256, so a database dump holds
-- no live session. A session expires after 30 days without a request.
CREATE TABLE sessions (
    id           bytea       PRIMARY KEY CHECK (octet_length(id) = 32),
    user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    csrf         text        NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    last_seen_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX sessions_user ON sessions (user_id);
CREATE INDEX sessions_last_seen ON sessions (last_seen_at);

-- API tokens: the secret is shown once and stored as its SHA-256.
CREATE TABLE tokens (
    id           uuid        PRIMARY KEY,
    user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    name         text        NOT NULL CHECK (char_length(name) BETWEEN 1 AND 64),
    hash         bytea       NOT NULL CHECK (octet_length(hash) = 32),
    scope        text        NOT NULL CHECK (scope IN ('submit', 'read')),
    created_at   timestamptz NOT NULL DEFAULT now(),
    last_used_at timestamptz,
    revoked_at   timestamptz,
    CONSTRAINT tokens_hash UNIQUE (hash)
);
CREATE INDEX tokens_user_live ON tokens (user_id, created_at) WHERE revoked_at IS NULL;

-- An entrant is a team (a solo player is a team of one); submissions, the
-- active bot and the rating belong to it.
CREATE TABLE teams (
    id         uuid        PRIMARY KEY,
    name       text        NOT NULL CHECK (char_length(name) BETWEEN 3 AND 32),
    created_by uuid        REFERENCES users (id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);
-- Names are unique ignoring case.
CREATE UNIQUE INDEX teams_name_lower ON teams (lower(name));

CREATE TABLE memberships (
    team_id   uuid        NOT NULL REFERENCES teams (id) ON DELETE CASCADE,
    user_id   uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role      text        NOT NULL CHECK (role IN ('owner', 'member')),
    joined_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT memberships_pkey PRIMARY KEY (team_id, user_id)
);
CREATE INDEX memberships_user ON memberships (user_id);
